def activateParkingBrake(mode, **_extra):
    import json, os, datetime
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0098000" if __import__("os").path.isdir("./environment_mix/0098000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = datetime.datetime.utcnow()

    # Ensure audit log exists and record every call
    audit_name = "audit.json"
    audits = _load(audit_name)
    if not isinstance(audits, list):
        audits = []
    endpoint = "activateParkingBrake"

    # Validate
    if not isinstance(mode, str) or mode not in ("engage", "release"):
        latency_ms = int((datetime.datetime.utcnow() - t0).total_seconds() * 1000)
        audits.append({"ts": t0.isoformat() + "Z", "endpoint": endpoint, "status": "error", "code": "VALIDATION_ERROR", "latency_ms": latency_ms})
        _save(audit_name, audits)
        return _err("VALIDATION_ERROR", "mode must be one of ['engage','release'].")

    # Load state rows
    state_rows = _load("state.json")
    if not isinstance(state_rows, list):
        state_rows = []
    if len(state_rows) == 0:
        latency_ms = int((datetime.datetime.utcnow() - t0).total_seconds() * 1000)
        audits.append({"ts": t0.isoformat() + "Z", "endpoint": endpoint, "status": "error", "code": "NOT_FOUND", "latency_ms": latency_ms})
        _save(audit_name, audits)
        return _err("NOT_FOUND", "Vehicle state is unavailable.")

    row = state_rows[0]
    if not isinstance(row, dict):
        latency_ms = int((datetime.datetime.utcnow() - t0).total_seconds() * 1000)
        audits.append({"ts": t0.isoformat() + "Z", "endpoint": endpoint, "status": "error", "code": "NOT_FOUND", "latency_ms": latency_ms})
        _save(audit_name, audits)
        return _err("NOT_FOUND", "Vehicle state is unavailable.")

    current = row.get("parkingBrakeStatus")
    # Normalize known values
    if current not in ("engaged", "released", None):
        # treat unknown as unavailable
        current = None

    if mode == "engage":
        if current == "engaged":
            latency_ms = int((datetime.datetime.utcnow() - t0).total_seconds() * 1000)
            audits.append({"ts": t0.isoformat() + "Z", "endpoint": endpoint, "status": "error", "code": "INVALID_TRANSITION", "latency_ms": latency_ms})
            _save(audit_name, audits)
            return _err("INVALID_TRANSITION", "Parking brake is already engaged.")
        row["parkingBrakeStatus"] = "engaged"
        # If force/slope exist, keep slope, set reasonable force; else set defaults
        row["_parkingBrakeForce"] = float(row.get("_parkingBrakeForce", 0.0)) if isinstance(row.get("_parkingBrakeForce", 0.0), (int, float)) else 0.0
        if row["_parkingBrakeForce"] <= 0:
            row["_parkingBrakeForce"] = 500.0
        if not isinstance(row.get("_slopeAngle"), (int, float)):
            row["_slopeAngle"] = 0.0
    else:  # release
        if current == "released":
            latency_ms = int((datetime.datetime.utcnow() - t0).total_seconds() * 1000)
            audits.append({"ts": t0.isoformat() + "Z", "endpoint": endpoint, "status": "error", "code": "INVALID_TRANSITION", "latency_ms": latency_ms})
            _save(audit_name, audits)
            return _err("INVALID_TRANSITION", "Parking brake is already released.")
        row["parkingBrakeStatus"] = "released"
        row["_parkingBrakeForce"] = 0.0
        if not isinstance(row.get("_slopeAngle"), (int, float)):
            row["_slopeAngle"] = 0.0

    state_rows[0] = row
    _save("state.json", state_rows)

    latency_ms = int((datetime.datetime.utcnow() - t0).total_seconds() * 1000)
    audits.append({"ts": t0.isoformat() + "Z", "endpoint": endpoint, "status": "ok", "code": None, "latency_ms": latency_ms})
    _save(audit_name, audits)

    return {
        "parkingBrakeStatus": row.get("parkingBrakeStatus"),
        "_parkingBrakeForce": row.get("_parkingBrakeForce"),
        "_slopeAngle": row.get("_slopeAngle"),
    }

