def fillFuelTank(fuelAmount):
    import json, os, math, random
    _S = json.load(open(os.path.join(_DB, 'state.json'), encoding='utf-8'))
    try:
        fuelAmount = float(fuelAmount)
    except (TypeError, ValueError):
        return {"error": "Fuel amount must be a number."}
    MAX, MIN = 50, 0.0
    level = _S.get("fuelLevel", 0.0)
    if fuelAmount < 0:
        return {"error": "Fuel amount cannot be negative."}
    if level + fuelAmount > MAX:
        return {"error": "Cannot fill gas above the tank capacity."}
    if level + fuelAmount < MIN:
        return {"error": "Fuel tank is empty. Min fuel level is 0 gallons."}
    return {"fuelLevel": level + fuelAmount}

def find_nearest_tire_shop(destination=None, **_extra):
    import json, os, datetime, hashlib
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0098000" if __import__("os").path.isdir("./environment_mix/0098000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = datetime.datetime.utcnow()
    audit_name = "audit.json"
    audits = _load(audit_name)
    if not isinstance(audits, list):
        audits = []
    endpoint = "find_nearest_tire_shop"

    if destination is not None and not isinstance(destination, str):
        latency_ms = int((datetime.datetime.utcnow() - t0).total_seconds() * 1000)
        audits.append({"ts": t0.isoformat() + "Z", "endpoint": endpoint, "status": "error", "code": "VALIDATION_ERROR", "latency_ms": latency_ms})
        _save(audit_name, audits)
        return _err("VALIDATION_ERROR", "destination must be a string when provided.")

    state_rows = _load("state.json")
    if not isinstance(state_rows, list):
        state_rows = []
    if len(state_rows) == 0 or not isinstance(state_rows[0], dict):
        latency_ms = int((datetime.datetime.utcnow() - t0).total_seconds() * 1000)
        audits.append({"ts": t0.isoformat() + "Z", "endpoint": endpoint, "status": "error", "code": "NOT_FOUND", "latency_ms": latency_ms})
        _save(audit_name, audits)
        return _err("NOT_FOUND", "Vehicle state is unavailable.")

    s = state_rows[0]
    query = destination
    if query is None or query.strip() == "":
        d0 = s.get("destination")
        if isinstance(d0, str) and d0.strip():
            query = d0.strip()

    if query is None or query.strip() == "":
        latency_ms = int((datetime.datetime.utcnow() - t0).total_seconds() * 1000)
        audits.append({"ts": t0.isoformat() + "Z", "endpoint": endpoint, "status": "error", "code": "VALIDATION_ERROR", "latency_ms": latency_ms})
        _save(audit_name, audits)
        return _err("VALIDATION_ERROR", "No destination provided and no current destination available.")

    # Offline deterministic "nearest shop" based on query hash; still depends on real state for destination.
    canned = [
        {"name": "Rivermist Tire & Auto", "address": "456 Oakwood Avenue, Rivermist, 83214", "phone": "+1-555-0101"},
        {"name": "Stonebrook Tire Center", "address": "88 Granite Road, Stonebrook, 74532", "phone": "+1-555-0102"},
        {"name": "Maplecrest Quick Tires", "address": "12 Maple Lane, Maplecrest, 56108", "phone": "+1-555-0103"},
        {"name": "Silverpine Wheel & Tire", "address": "240 Pine Street, Silverpine, 62947", "phone": "+1-555-0104"},
    ]
    h = int(hashlib.sha256(query.lower().encode("utf-8")).hexdigest(), 16)
    shop = canned[h % len(canned)]

    latency_ms = int((datetime.datetime.utcnow() - t0).total_seconds() * 1000)
    audits.append({"ts": t0.isoformat() + "Z", "endpoint": endpoint, "status": "ok", "code": None, "latency_ms": latency_ms})
    _save(audit_name, audits)

    return {"query": query, "nearest": shop}

