def lockDoors(unlock, door):
    import json, os, math, random
    _S = json.load(open(os.path.join(_DB, 'state.json'), encoding='utf-8'))
    door_status = dict(_S.get("doorStatus", {}))
    remaining = _S.get("remainingUnlockedDoors", 0)
    door = door or []
    if unlock:
        for d in door:
            if door_status.get(d) == "unlocked":
                continue
            door_status[d] = "unlocked"
            remaining += 1
        return {"lockStatus": "unlocked", "remainingUnlockedDoors": remaining}
    else:
        for d in door:
            if door_status.get(d) == "locked":
                continue
            door_status[d] = "locked"
            remaining -= 1
        return {"lockStatus": "locked", "remainingUnlockedDoors": remaining}

