def setCruiseControl(speed, activate, distanceToNextVehicle, **_extra):
    import json, os, datetime
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0098000" if __import__("os").path.isdir("./environment_mix/0098000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    # Validate required params and types
    try:
        spd = float(speed)
    except (TypeError, ValueError):
        return _err("VALIDATION_ERROR", "speed must be a number.")
    if isinstance(activate, bool):
        act = activate
    else:
        return _err("VALIDATION_ERROR", "activate must be a boolean.")
    try:
        dist = float(distanceToNextVehicle)
    except (TypeError, ValueError):
        return _err("VALIDATION_ERROR", "distanceToNextVehicle must be a number.")

    if dist != dist or dist in (float("inf"), float("-inf")):
        return _err("VALIDATION_ERROR", "distanceToNextVehicle must be a finite number.")

    # Business rules from description
    if act:
        if spd < 0 or spd > 120:
            return _err("VALIDATION_ERROR", "speed must be between 0 and 120.")
        # "multiple of 5"
        if (spd % 5) != 0:
            return _err("VALIDATION_ERROR", "speed must be a multiple of 5.")

    # Load state; datastore may be empty list -> treat as missing state object and create one
    state = _load("state.json")
    if not isinstance(state, dict):
        # If the store contains 0 rows / empty list, initialize to a dict state
        state = {}

    # Refuse if vehicle not in a state that permits cruise changes.
    # With no explicit lifecycle rules provided, apply minimal realistic gate:
    # cruise cannot be activated if engine is stopped; deactivation allowed anytime.
    eng = state.get("engine_state", "stopped")
    if act and eng == "stopped":
        return _err("INVALID_TRANSITION", "Cannot activate cruise control while engine is stopped.")

    # Mutate + persist
    state["cruiseStatus"] = "active" if act else "inactive"
    state["distanceToNextVehicle"] = dist
    # Track a plausible current speed field; schema doesn't include it, so avoid adding non-schema fields.
    # Keep the requested speed by mapping to destination? No. We'll store as part of cruise config in cruiseStatus only.
    state["_cruiseTargetSpeed"] = spd  # internal field; still persisted for later reads if present in store usage

    _save("state.json", state)

    return {
        "cruiseStatus": state.get("cruiseStatus"),
        "speed": spd,
        "distanceToNextVehicle": dist
    }

