                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    if not isinstance(ignitionMode, str) or not ignitionMode.strip():
        return _err("VALIDATION_ERROR", "ignitionMode must be provided.", allowed=["START", "STOP"])
    mode = ignitionMode.strip().upper()
    if mode not in ("START", "STOP"):
        return _err("VALIDATION_ERROR", "ignitionMode must be one of the supported values.", allowed=["START", "STOP"])

    state = _load("state.json")
    if not isinstance(state, dict):
        state = {}

    current = state.get("engine_state", "stopped")

    # Enforce transition legality (minimal, since no explicit lifecycle provided)
    if mode == "START":
