            # idempotent
            return {"engine_state": "running", "fuelLevel": state.get("fuelLevel"), "batteryVoltage": state.get("batteryVoltage")}
        state["engine_state"] = "running"
    else:  # STOP
        if current == "stopped":
            # idempotent
            return {"engine_state": "stopped", "fuelLevel": state.get("fuelLevel"), "batteryVoltage": state.get("batteryVoltage")}
        state["engine_state"] = "stopped"

    _save("state.json", state)

    return {
        "engine_state": state.get("engine_state"),
        "fuelLevel": state.get("fuelLevel"),
        "batteryVoltage": state.get("batteryVoltage")
    }
